        @Test
        @DisplayName("bhvAuthintegration006 AUTH-APPLIED: configured Bearer authenticator reaches a secured operation's outbound request")
        fun configuredAuthenticatorAppliedToSecuredOperation() {
            // Regression guard for the Elixir auth-drop bug: a client constructed
            // with a client-level authenticator must actually carry the credential
            // when a SECURED operation is invoked through the generated API class
            // (here PetApi.addPet, secured by apiKeyHeader/petStoreBearer). This
            // goes through the real generated operation method — which threads
            // the credential of the operation's own scheme into invokeApi and falls
            // back to the client-level authenticator — not just the generic invokeApi helper.
            val client = CapturingApiClient()
            val config = Configuration.builder().baseUrl("http://localhost").build()
            val authenticator =
                com.example.petstore.auth.BearerAuthenticator(
                    "http://localhost",
                    "secret-token-123",
                )
            val api = PetApi(client, config, authenticator)
            val pet =
                com.example.petstore.models
                    .Pet(name = "Rex", photoUrls = setOf("http://example.com/rex.png"))
            try {
                runBlocking { api.addPet(pet) }
            } catch (_: Exception) {
                // The capturing client returns {} which may fail Pet deserialization;
                // we only assert on the outbound credential, captured before the response.
            }
            assertEquals(
                "Bearer secret-token-123",
                client.capturedHeaders["Authorization"],
                "configured client-level authenticator must apply to a secured operation's outbound request",
            )
        }

        @Test
        @DisplayName("bhvAuthintegration005 SECURITY-NONE: client authenticator is suppressed for an unauthenticated operation")
        fun clientAuthenticatorSuppressedForSecurityNoneOperation() {
            // An operation declared `security: []` is explicitly unauthenticated.
            // Even when the client is constructed WITH an authenticator, invoking
            // such an operation through the generated API class (here
            // StoreApi.getInventory, declared security: []) must NOT attach the
            // client credential — the operation passes the NoAuth sentinel, which
            // BaseApi resolves to "no auth" rather than falling back to the
            // client-level authenticator. This guards against leaking the client
            // credential to unauthenticated endpoints (e.g. the testEcho* ops that
            // reflect the request back).
            val client = CapturingApiClient()
            val config = Configuration.builder().baseUrl("http://localhost").build()
            // Configure every auth surface the authenticator can populate:
            // an Authorization header, an api-key header, an api-key query param,
            // and an auth cookie. None of these may appear on the outbound request.
            val authenticator =
                TestAuthenticator(
                    mapOf("Authorization" to "Bearer client-secret", "api-key" to "header-key"),
                    mapOf("api_key" to "query-key"),
                    mapOf("session" to "cookie-value"),
                )
            val api = StoreApi(client, config, authenticator)
            try {
                runBlocking { api.getInventory() }
            } catch (_: Exception) {
                // The capturing client returns {} which may fail deserialization;
                // we only assert on the (absence of) outbound credential.
            }
            assertFalse(
                client.capturedHeaders.containsKey("Authorization"),
                "unauthenticated operation must NOT carry the client Authorization header",
            )
            assertFalse(
                client.capturedHeaders.containsKey("api-key"),
                "unauthenticated operation must NOT carry the client api-key header",
            )
            assertFalse(
                client.capturedUrl.contains("api_key="),
                "unauthenticated operation must NOT carry the client api-key query param",
            )
            assertFalse(
                client.capturedHeaders.containsKey("Cookie"),
                "unauthenticated operation must NOT carry the client auth cookie",
            )
        }

        @Test
        @DisplayName(
            "bhvAuthintegration012 INHERITED-SECURITY: client authenticator is applied to an operation that inherits the global requirement",
        )
        fun clientAuthenticatorAppliedForInheritedSecurityOperation() {
            // getPetById declares no security of its own, so it inherits the
            // global requirement. This generator strips the inherited auth
            // methods off such an operation, so the generated method passes null
            // (not the NoAuth sentinel) and BaseApi falls back to the client-level
            // authenticator. A configured client credential MUST reach the wire —
            // the regression that silently dropped auth on every inherited-security
            // operation.
            val client = CapturingApiClient()
            val config = Configuration.builder().baseUrl("http://localhost").build()
            val authenticator =
                TestAuthenticator(
                    mapOf("Authorization" to "Bearer client-secret"),
                    emptyMap(),
                    emptyMap(),
                )
            val api = PetApi(client, config, authenticator)
            try {
                runBlocking { api.getPetById(42L) }
            } catch (_: Exception) {
                // The capturing client returns {} which may fail Pet deserialization;
                // we only assert on the outbound credential, captured before the response.
            }
            assertEquals(
                "Bearer client-secret",
                client.capturedHeaders["Authorization"],
                "inherited-security operation must carry the client Authorization header",
            )
        }
    }

    @Nested
