        @Test
        @DisplayName("bhvSerializationwire012 form-urlencoded body encodes space as + not %20")
        fun formUrlencodedBodyEncodesSpaceAsPlus() {
            // form-urlencoded-space-plus-vs-pct20: application/x-www-form-urlencoded
            // mandates '+' for a space (WHATWG/HTML form-encoding), not '%20'.
            // The encoder uses encodeURLQueryComponent(spaceToPlus = true).
            val client = CapturingApiClient()
            val testApi = TestableApiWithClient(client, "http://localhost")
            runBlocking {
                testApi.call(
                    "POST",
                    "/test/echo",
                    body = mapOf("full name" to "Ada Lovelace"),
                    contentType = "application/x-www-form-urlencoded",
                )
            }
            assertNotNull(client.capturedBody)
            val wire = client.capturedBody.toString()
            assertEquals("full+name=Ada+Lovelace", wire)
            assertFalse(wire.contains("%20"))
        }

        @Test
        @DisplayName("bhvSerializationwire055 a space in a form value encodes as plus, never %20")
        fun formSpaceEncodedAsPlusInEveryValue() {
            val client = CapturingApiClient()
            val testApi = TestableApiWithClient(client, "http://localhost")
            runBlocking {
                testApi.call(
                    "POST",
                    "/test/echo",
                    body = mapOf("nickname" to "Good Boy", "note" to "very fast"),
                    contentType = "application/x-www-form-urlencoded",
                )
            }
            assertNotNull(client.capturedBody)
            val wire = client.capturedBody.toString()
            assertTrue(wire.contains("nickname=Good+Boy"), "got: $wire")
            assertTrue(wire.contains("note=very+fast"), "got: $wire")
            assertFalse(wire.contains("%20"), "got: $wire")
        }

        @Test
        @DisplayName("form-urlencoded body percent-encodes reserved characters in keys and values")
        fun formUrlencodedBodyEncodesReservedCharacters() {
