    @Nested
    @DisplayName("header flow-through")
    inner class HeaderFlowThrough {
        @Test
        @DisplayName("bhvSerializationwire007 empty content-type defaults to application/json")
        fun emptyContentTypeDefaultsToJson() {
            val client = CapturingApiClient()
            val testApi = TestableApiWithClient(client, "http://localhost")
            runBlocking {
                testApi.call("POST", "/test/echo", body = mapOf("name" to "test"), contentType = "")
            }
            assertEquals("application/json", client.capturedHeaders["Content-Type"])
        }

        @Test
        @DisplayName("bhvOperations002 all headers from selector flow through to request")
        fun allHeadersFlowThrough() {
            val client = CapturingApiClient()
            val testApi = TestableApiWithClient(client, "http://localhost")
            runBlocking {
                testApi.call("POST", "/test/echo", body = mapOf("name" to "test"))
            }
            assertTrue(client.capturedHeaders.containsKey("Accept"))
            assertTrue(client.capturedHeaders.containsKey("Content-Type"))
        }

        @Test
        @DisplayName("bhvOptions001 R5-1: config default Accept wins over the operation-negotiated Accept")
        fun configDefaultAcceptWinsOverNegotiated() {
            // The operation negotiates Accept=application/json, but a client
            // config default header of Accept=application/xml must win: the
            // selector's negotiated value is applied first, then the config
            // defaults are merged OVER it, so the outgoing request carries the
            // caller's configured Accept. Matches java/elixir/python.
            val client = CapturingApiClient()
            val config =
                Configuration
                    .builder()
                    .baseUrl("http://localhost")
                    .defaultHeader("Accept", "application/xml")
                    .build()
            val testApi = TestableApiWithConfig(client, config)
            runBlocking {
                testApi.call("GET", "/test/echo", accepts = arrayOf("application/json"))
            }
            assertEquals(
                "application/xml",
                client.capturedHeaders["Accept"],
                "config default Accept must override the operation-negotiated application/json",
            )
        }

        @Test
        @DisplayName("bhvOperations008 config default headers Accept wins over every negotiated Accept value")
        fun configDefaultHeadersAcceptWinsOverAllNegotiatedValues() {
            val client = CapturingApiClient()
            val config =
                Configuration
                    .builder()
                    .baseUrl("http://localhost")
                    .defaultHeader("Accept", "application/xml")
                    .build()
            val testApi = TestableApiWithConfig(client, config)
            runBlocking {
                testApi.call("GET", "/test/echo", accepts = arrayOf("application/json", "text/plain"))
            }
            assertEquals(
                "application/xml",
                client.capturedHeaders["Accept"],
                "the configured Accept must replace the whole negotiated list",
            )
        }
    }

    // ── Binary response tests (Gap 3+4) ──

    @Nested
    @DisplayName("BinaryResponseTests")
    inner class BinaryResponseTests {
        @Test
        @DisplayName("bhvSerializationwire018 octet-stream base64 body decodes to correct bytes (strong roundtrip)")
        fun octetStreamBase64DecodesToCorrectBytes() {
            // Original bytes include 0x00 and 0xFF — values that would mangle under UTF-8 conversion.
            val original = byteArrayOf(0x00, 0xFF.toByte(), 0x42)
            val encoded =
                java.util.Base64
                    .getEncoder()
                    .encodeToString(original)
            val client =
                object : CapturingApiClient() {
                    override suspend fun sendRequest(
                        method: String,
                        url: String,
                        headers: Map<String, String>,
                        body: Any?,
                        noRedirect: Boolean,
                    ): ApiHttpResponse = ApiHttpResponse(200, encoded, mapOf("Content-Type" to "application/octet-stream"))
                }
            val response = runBlocking { client.sendRequest("GET", "/api/binary", emptyMap(), null) }
            val decoded =
                java.util.Base64
                    .getDecoder()
                    .decode(response.body)
            assertArrayEquals(original, decoded, "binary roundtrip must preserve bytes exactly")
        }

        @Test
        @DisplayName("bhvOperations012 image/png response body represents bytes not plain text")
        fun imagePngResponseRepresentsBytes() {
            val client =
                object : CapturingApiClient() {
                    override suspend fun sendRequest(
                        method: String,
                        url: String,
                        headers: Map<String, String>,
                        body: Any?,
                        noRedirect: Boolean,
                    ): ApiHttpResponse = ApiHttpResponse(200, "iVBORw0KGgo=", mapOf("Content-Type" to "image/png"))
                }
            val response = runBlocking { client.sendRequest("GET", "/api/image", emptyMap(), null) }
            val decoded =
                java.util.Base64
                    .getDecoder()
                    .decode(response.body)
            assertNotNull(decoded)
            assertTrue(decoded.isNotEmpty())
        }

        @Test
        @DisplayName("bhvSerializationwire017 octet-stream binary response roundtrips exactly via base64 decode")
        fun octetStreamResponseRoundtripsThroughCallForResult() {
            val original = byteArrayOf(0x00, 0xFF.toByte(), 0x42, 0x0A, 0x0D)
            val encoded =
                java.util.Base64
                    .getEncoder()
                    .encodeToString(original)
            val client =
                object : CapturingApiClient() {
                    override suspend fun sendRequest(
                        method: String,
                        url: String,
                        headers: Map<String, String>,
                        body: Any?,
                        noRedirect: Boolean,
