        @Test
        @DisplayName("bhvErrors035 text/plain response for a non-String return type is a serialization error naming the Content-Type")
        fun textPlainResponseForNonStringTypeIsSerializationError() {
            val client =
                object : CapturingApiClient() {
                    override suspend fun sendRequest(
                        method: String,
                        url: String,
                        headers: Map<String, String>,
                        body: Any?,
                        noRedirect: Boolean,
                    ): ApiHttpResponse = ApiHttpResponse(200, "hello", mapOf("Content-Type" to "text/plain; charset=utf-8"))
                }
            val testApi = TestableApiWithClient(client, "http://localhost")
            val ex =
                assertThrows(
                    com.example.petstore.errors.SerializationException::class.java,
                ) {
                    runBlocking {
                        testApi.callForResult<Int>(
                            "GET",
                            "/api/text",
                            accepts = arrayOf("text/plain"),
                            operation = "PetApi.getText",
