    // ── Proxy authentication tests (Gap 29) ──

    @Nested
    @DisplayName("ProxyAuthTests")
    inner class ProxyAuthTests {
        @Test
        @DisplayName("bhvTransport001 proxy URL with embedded basic-auth credentials routes through proxy")
        fun proxyUrlWithBasicAuthCredentialsRoutesThroughProxy() {
            val chasmUrl = ChasmContainer.getInternalHttpUrl()
            val proxyHostPort = SquidContainer.getAuthProxyUrl().removePrefix("http://")
            val authenticatedProxy = "http://user:pass@$proxyHostPort"
            val transport =
                TransportOptions
                    .builder()
                    .proxy(authenticatedProxy)
                    .build()
            val client = DefaultApiClient(transport)
            val response =
                runBlocking {
                    client.sendRequest("GET", "$chasmUrl/test/echo", emptyMap(), null)
                }
            assertEquals(200, response.statusCode)
            assertTrue(response.body.contains("\"method\""))
        }

        @Test
        @DisplayName("bhvTransport059 an authenticating proxy refuses a request without credentials")
        fun proxyWithoutCredentialsIsRefused() {
            val chasmUrl = ChasmContainer.getInternalHttpUrl()
            val transport =
                TransportOptions
                    .builder()
                    .proxy(SquidContainer.getAuthProxyUrl())
                    .build()
            val client = DefaultApiClient(transport)
            val response =
                runBlocking {
                    client.sendRequest("GET", "$chasmUrl/test/echo", emptyMap(), null)
                }
            assertEquals(407, response.statusCode)
        }

        @Test
        @DisplayName("bhvOptions052 a proxy URL carrying credentials is accepted")
        fun transportOptionsAcceptsProxyWithBasicAuthCredentials() {
            // Verifies the proxy URL parser does not reject user:pass@host:port form.
            val opts =
                TransportOptions
                    .builder()
                    .proxy("http://user:pass@proxy.example.com:3128")
                    .build()
            assertEquals("http://user:pass@proxy.example.com:3128", opts.proxy)
        }
    }

